/**
 * @method
 * @name bingx#fetchTime
 * @description fetches the current integer timestamp in milliseconds from the bingx server
 * @see https://bingx-api.github.io/docs/#/swapV2/base-info.html#Get%20Server%20Time
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int} the current integer timestamp in milliseconds from the bingx server
 */
func (this *Bingx) FetchTimeAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTimeBody(ch, optionalArgs...)
	return ch
}
func (this *Bingx) fetchTimeBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = MapTyped(PanicOnError((<-this.SwapV2PublicGetServerTime(params)).Raw))
	//
	//    {
	//        "code": 0,
	//        "msg": "",
	//        "data": {
	//            "serverTime": 1675319535362
	//        }
	//    }
	//
	var data map[string]any = SafeMapTyped(response, "data")

	ch <- this.SafeInteger(data, "serverTime")
	return nil
}

/**
 * @method
 * @name bingx#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://bingx-api.github.io/docs-v3/#/en/Account%20and%20Wallet/Wallet%20Deposits%20and%20Withdrawals/Query%20currency%20deposit%20and%20withdrawal%20data
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Bingx) FetchCurrenciesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Bingx) fetchCurrenciesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if !this.CheckRequiredCredentials(false) {

		ch <- map[string]any{}
		return nil
	}
	var isSandbox *bool = this.SafeBool(this.Options, "sandboxMode", false)
	if isSandbox != nil && *isSandbox == true {

		ch <- map[string]any{}
		return nil
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.WalletsV1PrivateGetCapitalConfigGetall(params)).Raw))
	//
	//    {
	//        "code": "0",
	//        "timestamp": "1779364918914",
	//        "data": [
	//            {
	//                "coin": "BTC",
	//                "name": "BTC",
	//                "networkList": [
	//                    {
	//                        "name": "BTC",
	//                        "network": "BTC",
	//                        "isDefault": true,
	//                        "minConfirm": "2",
	//                        "withdrawEnable": true,
	//                        "depositEnable": true,
	//                        "withdrawFee": "0.00004",
	//                        "withdrawMax": "64.77131128",
	//                        "withdrawMin": "0.000046",
	//                        "depositMin": "0.00009",
	//                        "withdrawPrecision": "8",
	//                        "depositPrecision": "8",
	//                        "contractAddress": "",
	//                        "needTagOrMemo": "false",
	//                        "displayName": "BTC"
	//                    },
	//                    {
	//                        "name": "BTC",
	//                        "network": "BEP20",
	//                        "isDefault": true,
	//                        "minConfirm": "10",
	//                        "withdrawEnable": true,
	//                        "depositEnable": true,
	//                        "withdrawFee": "0.000001",
	//                        "withdrawMax": "64.77131128",
	//                        "withdrawMin": "0.000065",
	//                        "depositMin": "0.000012",
	//                        "withdrawPrecision": "8",
	//                        "depositPrecision": "18",
	//                        "contractAddress": "0x7130d2a12b9bcbfae4f2634d864a1ee1ce3ead9c",
	//                        "needTagOrMemo": "false",
	//                        "displayName": "BTCBEP20"
	//                    }
	//                ]
	//            },
	//            ...
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseCurrencies(data)
	return nil
}
func (this *Bingx) ParseCurrency(rawCurrency any) any {
	var currencyId *string = this.SafeString(rawCurrency, "coin")
	var code *string = this.SafeCurrencyCode(currencyId)
	var name *string = this.SafeString(rawCurrency, "name")
	var networkList []any = SafeListTyped(rawCurrency, "networkList")
	var networks map[string]any = map[string]any{}
	for j := 0; j < len(networkList); j++ {
		var rawNetwork any = func() any {
			if j >= 0 && j < len(networkList) {
				return DerefScalar(networkList[j])
			}
			return nil
		}()
		var network *string = this.SafeString(rawNetwork, "network")
		var networkCode *string = this.NetworkIdToCode(network, code)
		var limits map[string]any = map[string]any{
			"withdraw": map[string]any{
				"min": this.SafeNumber(rawNetwork, "withdrawMin"),
				"max": this.SafeNumber(rawNetwork, "withdrawMax"),
			},
			"deposit": map[string]any{
				"min": this.SafeNumber(rawNetwork, "depositMin"),
				"max": nil,
			},
		}
		var precision *float64 = Float64PtrTyped(this.ParseNumber(this.ParsePrecision(this.SafeString(rawNetwork, "withdrawPrecision"))))
		if networkCode != nil {
			AddElementToObject(networks, networkCode, map[string]any{
				"info":      rawNetwork,
				"id":        network,
				"network":   networkCode,
				"fee":       this.SafeNumber(rawNetwork, "withdrawFee"),
				"active":    nil,
				"deposit":   this.SafeBool(rawNetwork, "depositEnable"),
				"withdraw":  this.SafeBool(rawNetwork, "withdrawEnable"),
				"precision": precision,
				"limits":    limits,
			})
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"info":      rawCurrency,
		"code":      code,
		"id":        currencyId,
		"precision": nil,
		"name":      name,
		"active":    nil,
		"deposit":   nil,
		"withdraw":  nil,
		"networks":  networks,
		"fee":       nil,
		"limits":    nil,
		"type":      "crypto",
	})
}
