func (this *Bingx) ParseMarket(market any) any {
	var id *string = this.SafeString(market, "symbol")
	var symbolParts []string = strings.Split(*id, "-")
	var baseId *string = SafeStringPtr(GetValue(symbolParts, 0))
	var quoteId *string = SafeStringPtr(GetValue(symbolParts, 1))
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	var currency *string = this.SafeString(market, "currency")
	var checkIsInverse bool = false
	var checkIsLinear bool = true
	var inverseContractSize *float64 = this.SafeNumber(market, "minTickSize")
	if inverseContractSize != nil {
		// inverse swap market
		currency = baseId
		checkIsInverse = true
		checkIsLinear = false
	}
	var settle *string = this.SafeCurrencyCode(currency)
	var pricePrecision any = DerefScalar(this.SafeNumber(market, "tickSize"))
	if IsEqual(pricePrecision, nil) {
		pricePrecision = this.ParseNumber(this.ParsePrecision(this.SafeString(market, "pricePrecision")))
	}
	var quantityPrecision any = DerefScalar(this.SafeNumber(market, "stepSize"))
	if IsEqual(quantityPrecision, nil) {
		quantityPrecision = this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quantityPrecision")))
	}
	var typeVar string = "spot"
	if settle != nil {
		typeVar = "swap"
	}
	var spot bool = (typeVar == "spot")
	var swap bool = (typeVar == "swap")
	var symbol any = Add(Add(base, "/"), quote)
	if settle != nil {
		symbol = Add(symbol, ":"+*settle)
	}
	var fees map[string]any = SafeMapTyped(this.Fees, typeVar)
	var contractSize any = nil
	if swap {
		contractSize = func() any {
			if checkIsInverse {
				return inverseContractSize
			}
			return this.ParseNumber("1")
		}()
	}
	var isActive bool = false
	if (this.SafeString(market, "apiStateOpen") != nil && *this.SafeString(market, "apiStateOpen") == "true") && (this.SafeString(market, "apiStateClose") != nil && *this.SafeString(market, "apiStateClose") == "true") {
		isActive = true // swap active
	} else if (IsEqual(this.SafeBool(market, "apiStateSell"), true)) && (IsEqual(this.SafeBool(market, "apiStateBuy"), true)) && (this.SafeString(market, "status") != nil && *this.SafeString(market, "status") == "1") {
		isActive = true // spot active
	} else if checkIsInverse && (this.SafeString(market, "status") != nil && *this.SafeString(market, "status") == "1") {
		isActive = true // inverse swap active
	}
	var isInverse *bool = func() *bool {
		if spot {
			return nil
		}
		return SafeBoolPtr(checkIsInverse)
	}()
	var isLinear *bool = func() *bool {
		if spot {
			return nil
		}
		return SafeBoolPtr(checkIsLinear)
	}()
	var minAmount *float64 = nil
	if !spot {
		minAmount = this.SafeNumber2(market, "minQty", "tradeMinQuantity")
	}
	var timeOnline *int64 = this.SafeInteger(market, "timeOnline")
	if timeOnline != nil && *timeOnline == 0 {
		timeOnline = nil
	}
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       currency,
		"type":           typeVar,
		"spot":           spot,
		"margin":         false,
		"swap":           swap,
		"future":         false,
		"option":         false,
		"active":         isActive,
		"contract":       swap,
		"linear":         isLinear,
		"inverse":        isInverse,
		"taker":          this.SafeNumber(fees, "taker"),
		"maker":          this.SafeNumber(fees, "maker"),
		"feeSide":        this.SafeString(fees, "feeSide"),
		"contractSize":   contractSize,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": quantityPrecision,
			"price":  pricePrecision,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": minAmount,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": this.SafeNumberN(market, []any{"minNotional", "tradeMinUSDT", "minTradeValue"}),
				"max": this.SafeNumber(market, "maxNotional"),
			},
		},
		"created": timeOnline,
		"info":    market,
	})
}

/**
 * @method
 * @name bingx#fetchMarkets
 * @description retrieves data on all markets for bingx
 * @see https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Spot%20trading%20symbols
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/USDT-M%20Perp%20Futures%20symbols
 * @see https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Contract%20Information
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Bingx) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Bingx) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var requests []any = []any{this.FetchSwapMarketsAsync(params)}
	var isSandbox *bool = this.SafeBool(this.Options, "sandboxMode", false)
	if isSandbox == nil || *isSandbox != true {
		requests = append(requests, this.FetchInverseSwapMarketsAsync(params))
		requests = append(requests, this.FetchSpotMarketsAsync(params)) // sandbox is swap only
	}

	var promises []any = ListTyped(PanicOnError((<-promiseAll(requests))))
	var linearSwapMarkets []any = SafeListTypedDefault(promises, 0, []any{})
	var inverseSwapMarkets []any = SafeListTypedDefault(promises, 1, []any{})
	var spotMarkets []any = SafeListTypedDefault(promises, 2, []any{})
	var swapMarkets []any = this.ArrayConcat(linearSwapMarkets, inverseSwapMarkets)

	ch <- this.ArrayConcat(spotMarkets, swapMarkets)
	return nil
}

/**
 * @method
 * @name bingx#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Kline%2FCandlestick%20Data
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Kline%2FCandlestick%20Data
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20Kline%2FCandlestick%20Data
 * @see https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Get%20K-line%20Data
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch (max 1000 for inverse swaps, 1440 otherwise)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Bingx) FetchOHLCVAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bingx) fetchOHLCVBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	var maxLimit int = func() int {
		if GetValue(market, "inverse") == true {
			return 1000
		}
		return 1440
	}()
	var paginate bool = false
	var paginateparamsVariable []any = this.HandleOptionBoolAndParams(params, "fetchOHLCV", "paginate", false)
	paginate = GetValueBool(paginateparamsVariable, 0, false)
	params = MapTyped(GetValue(paginateparamsVariable, 1))
	if paginate {

		var retRes121919 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, params, maxLimit))))
		ch <- BoxAbsent(retRes121919)
		return nil
	}
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	request["interval"] = this.SafeString(this.Timeframes, timeframe, timeframe)
	var requestLimit any = func() any {
		if limit == nil {
			return 500
		}
		return mathMin(limit, maxLimit)
	}()
	if since != nil {
		request["startTime"] = mathMax(Subtract(since, 1), 0)
	}
	if limit != nil {
		request["limit"] = requestLimit
	}
	var until *int64 = this.SafeInteger2(params, "until", "endTime")
	if until != nil {
		params = MapTyped(this.Omit(params, []any{"until"}))
		request["endTime"] = until
	} else if (GetValue(market, "inverse") == true) && (since != nil) {
		var duration int64 = this.ParseTimeframe(timeframe) * 1000
		request["endTime"] = this.Sum(since, Multiply(duration, requestLimit))
	}
	var response map[string]any = nil
	if GetValue(market, "spot") == true {
		// bingx spot klines are anchored to UTC+8 by default, unlike the swap klines and other exchanges
		// the timeZone request parameter aligns the candle boundaries to UTC, live-verified for the spot endpoint
		var timeZone any = nil
		var timeZoneparamsVariable []any = this.HandleOptionIntegerAndParams(params, "fetchOHLCV", "timeZone", 0)
		timeZone = GetValue(timeZoneparamsVariable, 0)
		params = MapTyped(GetValue(timeZoneparamsVariable, 1))
		if !IsEqual(timeZone, nil) {
			request["timeZone"] = timeZone
		}

		response = MapTyped(PanicOnError((<-this.SpotV1PublicGetMarketKline(this.Extend(request, params))).Raw))
	} else {
		if GetValue(market, "inverse") == true {

			response = MapTyped(PanicOnError((<-this.CswapV1PublicGetMarketKlines(this.Extend(request, params))).Raw))
		} else {
			var price *string = this.SafeString(params, "price")
			params = MapTyped(this.Omit(params, "price"))
			if price != nil && *price == "mark" {

				response = MapTyped(PanicOnError((<-this.SwapV1PublicGetMarketMarkPriceKlines(this.Extend(request, params))).Raw))
			} else {

				response = MapTyped(PanicOnError((<-this.SwapV3PublicGetQuoteKlines(this.Extend(request, params))).Raw))
			}
		}
	}
	//
	//    {
	//        "code": 0,
	//        "msg": "",
	//        "data": [
	//          {
	//            "open": "19396.8",
	//            "close": "19394.4",
	//            "high": "19397.5",
	//            "low": "19385.7",
	//            "volume": "110.05",
	//            "time": 1666583700000
	//          },
	//          ...
	//        ]
	//    }
	//
	// fetchMarkOHLCV
	//
	//    {
	//        "code": 0,
	//        "msg": "",
	//        "data": [
	//            {
	//                "open": "42191.7",
	//                "close": "42189.5",
	//                "high": "42196.5",
	//                "low": "42189.5",
	//                "volume": "0.00",
	//                "openTime": 1706508840000,
	//                "closeTime": 1706508840000
	//            }
	//        ]
	//    }
	//
	var ohlcvs any = this.SafeValue(response, "data", []any{})
	if !IsArray(ohlcvs) {
		ohlcvs = []any{ohlcvs}
	}

	ch <- this.ParseOHLCVs(ohlcvs, market, timeframe, since, limit)
	return nil
}
func (this *Bingx) ParseOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//    {
	//        "open": "19394.4",
	//        "close": "19379.0",
	//        "high": "19394.4",
	//        "low": "19368.3",
	//        "volume": "167.44",
	//        "time": 1666584000000
	//    }
	//
	// fetchMarkOHLCV
	//
	//    {
	//        "open": "42191.7",
	//        "close": "42189.5",
	//        "high": "42196.5",
	//        "low": "42189.5",
	//        "volume": "0.00",
	//        "openTime": 1706508840000,
	//        "closeTime": 1706508840000
	//    }
	// spot
	//    [
	//        1691402580000,
	//        29093.61,
	//        29093.93,
	//        29087.73,
	//        29093.24,
	//        0.59,
	//        1691402639999,
	//        17221.07
	//    ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	if IsArray(ohlcv) {
		return []any{this.SafeInteger(ohlcv, 0), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 4), this.SafeNumber(ohlcv, 5)}
	}
	return []any{this.SafeInteger2(ohlcv, "time", "closeTime"), this.SafeNumber(ohlcv, "open"), this.SafeNumber(ohlcv, "high"), this.SafeNumber(ohlcv, "low"), this.SafeNumber(ohlcv, "close"), this.SafeNumber(ohlcv, "volume")}
}

/**
 * @method
 * @name bingx#fetchTrades
 * @description get the list of most recent trades for a particular symbol
 * @see https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Recent%20Trades%20List
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Recent%20Trades%20List
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Bingx) FetchTradesAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bingx) fetchTradesBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	if GetValue(market, "inverse") == true {
		panic(NotSupported(this.Id + " fetchTrades() is not supported for inverse swap markets"))
	}
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	var response map[string]any = nil
	var marketType *string = nil
	var marketTypeparamsVariable []any = this.HandleMarketTypeAndParams("fetchTrades", market, params)
	marketType = SafeStringPtr(GetValue(marketTypeparamsVariable, 0))
	params = MapTyped(GetValue(marketTypeparamsVariable, 1))
	if limit != nil {
		var maxLimit int = func() int {
			if marketType != nil && *marketType == "spot" {
				return 500
			}
			return 1000
		}()
		request["limit"] = mathMin(limit, maxLimit)
	}
	if marketType != nil && *marketType == "spot" {

		response = MapTyped(PanicOnError((<-this.SpotV1PublicGetMarketTrades(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.SwapV2PublicGetQuoteTrades(this.Extend(request, params))).Raw))
	}
	//
	// spot
	//
	//    {
	//        "code": 0,
	//        "data": [
	//            {
	//                "id": 43148253,
	//                "price": 25714.71,
	//                "qty": 1.674571,
	//                "time": 1655085975589,
	//                "buyerMaker": false
	//            }
	//        ]
	//    }
	//
	// swap
	//
	//    {
	//      "code":0,
	//      "msg":"",
	//      "data":[
	//        {
	//          "time": 1672025549368,
	//          "isBuyerMaker": true,
	//          "price": "16885.0",
	//          "qty": "3.3002",
	//          "quoteQty": "55723.87"
	//        },
	//        ...
	//      ]
	//    }
	//
	var trades []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseTrades(trades, market, since, limit)
	return nil
}
func (this *Bingx) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// spot fetchTrades
	//
	//    {
	//        "id": 43148253,
	//        "price": 25714.71,
	//        "qty": 1.674571,
	//        "time": 1655085975589,
	//        "buyerMaker": false
	//    }
	//
	// spot fetchMyTrades
	//
	//     {
	//         "symbol": "LTC-USDT",
	//         "id": 36237072,
	//         "orderId": 1674069326895775744,
	//         "price": "85.891",
	//         "qty": "0.0582",
	//         "quoteQty": "4.9988562000000005",
	//         "commission": -0.00005820000000000001,
	//         "commissionAsset": "LTC",
	//         "time": 1687964205000,
	//         "isBuyer": true,
	//         "isMaker": false
	//     }
	//
	// swap fetchTrades
	//
	//    {
	//        "time": 1672025549368,
	//        "isBuyerMaker": true,
	//        "price": "16885.0",
	//        "qty": "3.3002",
	//        "quoteQty": "55723.87"
	//    }
	//
	// swap fetchMyTrades
	//
	//    {
	//        "volume": "0.1",
	//        "price": "106.75",
	//        "amount": "10.6750",
	//        "commission": "-0.0053",
	//        "currency": "USDT",
	//        "orderId": "1676213270274379776",
	//        "liquidatedPrice": "0.00",
	//        "liquidatedMarginRatio": "0.00",
	//        "filledTime": "2023-07-04T20:56:01.000+0800"
	//    }
	//
	// ws spot
	//
	//    {
	//        "E": 1690214529432,
	//        "T": 1690214529386,
	//        "e": "trade",
	//        "m": true,
	//        "p": "29110.19",
	//        "q": "0.1868",
	//        "s": "BTC-USDT",
	//        "t": "57903921"
	//    }
	//
	// ws linear swap
	//
	//    {
	//        "q": "0.0421",
	//        "p": "29023.5",
	//        "T": 1690221401344,
	//        "m": false,
	//        "s": "BTC-USDT"
	//    }
	//
	// ws inverse swap
	//
	//     {
	//         "e": "trade",
	//         "E": 1722920589665,
	//         "s": "BTC-USD",
	//         "t": "39125001",
	//         "p": "55360.0",
	//         "q": "1",
	//         "T": 1722920589582,
	//         "m": false
	//     }
	//
	// inverse swap fetchMyTrades
	//
	//     {
	//         "orderId": "1817441228670648320",
	//         "symbol": "SOL-USD",
	//         "type": "MARKET",
	//         "side": "BUY",
	//         "positionSide": "LONG",
	//         "tradeId": "97244554",
	//         "volume": "2",
	//         "tradePrice": "182.652",
	//         "amount": "20.00000000",
	//         "realizedPnl": "0.00000000",
	//         "commission": "-0.00005475",
	//         "currency": "SOL",
	//         "buyer": true,
	//         "maker": false,
	//         "tradeTime": 1722146730000
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var time *int64 = this.SafeIntegerN(trade, []any{"time", "filledTm", "T", "tradeTime"})
	var datetimeId *string = this.SafeString(trade, "filledTm")
	if datetimeId != nil {
		time = this.Parse8601(datetimeId)
	}
	if time != nil && *time == 0 {
		time = nil
	}
	var cost *string = this.SafeString(trade, "quoteQty")
	// const type = (cost === undefined) ? 'spot' : 'swap'; this is not reliable
	var currencyId *string = this.SafeStringN(trade, []any{"currency", "N", "commissionAsset"})
	var currencyCode *string = this.SafeCurrencyCode(currencyId)
	var m *bool = this.SafeBool(trade, "m")
	var marketId *string = this.SafeString2(trade, "s", "symbol")
	var isBuyerMaker *bool = this.SafeBoolN(trade, []any{"buyerMaker", "isBuyerMaker", "maker"})
	var takeOrMaker any = nil
	var isMakerSide bool = (isBuyerMaker != nil && *isBuyerMaker == true) || (m != nil && *m == true)
	if (isBuyerMaker != nil) || (m != nil) {
		takeOrMaker = func() string {
			if isMakerSide {
				return "maker"
			}
			return "taker"
		}()
	}
	var side *string = this.SafeStringLower2(trade, "side", "S")
	if side == nil {
		if (isBuyerMaker != nil) || (m != nil) {
			side = SafeStringPtr(func() string {
				if isMakerSide {
					return "sell"
				}
				return "buy"
			}())
			takeOrMaker = "taker"
		}
	}
	var isBuyer *bool = this.SafeBool(trade, "isBuyer")
	if isBuyer != nil {
		side = SafeStringPtr(func() string {
			if isBuyer != nil && *isBuyer {
				return "buy"
			}
			return "sell"
		}())
	}
	var isMaker *bool = this.SafeBool(trade, "isMaker")
	if isMaker != nil {
		takeOrMaker = func() string {
			if isMaker != nil && *isMaker {
				return "maker"
			}
			return "taker"
		}()
	}
	var amount *string = this.SafeStringN(trade, []any{"qty", "amount", "q"})
	if (market != nil) && (GetValue(market, "swap") == true) && (InOp(trade, "volume")) {
		// Linear volume is the base quantity (contractSize 1); inverse volume is the contract count.
		// safeTrade applies contractSize when calculating inverse cost.
		amount = this.SafeString(trade, "volume")
	}
	var price *string = this.SafeStringN(trade, []any{"price", "p", "tradePrice"})
	if (market != nil) && (GetValue(market, "linear") == true) && (this.SafeString(trade, "x") != nil && *this.SafeString(trade, "x") == "TRADE") {
		var lastAmount *string = this.SafeString(trade, "l")
		var lastPrice *string = this.SafeString(trade, "L")
		if (lastAmount != nil) && (lastPrice != nil) {
			// Linear WS l/L describe the last fill, not the original order's q/p.
			amount = lastAmount
			price = lastPrice
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           this.SafeStringN(trade, []any{"id", "t", "fillId", "tradeId"}),
		"info":         trade,
		"timestamp":    time,
		"datetime":     this.Iso8601(time),
		"symbol":       this.SafeSymbol(marketId, market, "-"),
		"order":        this.SafeString2(trade, "orderId", "i"),
		"type":         this.SafeStringLower(trade, "o"),
		"side":         this.ParseOrderSide(side),
		"takerOrMaker": takeOrMaker,
		"price":        price,
		"amount":       amount,
		"cost":         cost,
		"fee": map[string]any{
			"cost":     this.ParseNumber(Precise.StringAbs(this.SafeString2(trade, "commission", "n"))),
			"currency": currencyCode,
		},
	}, market)
}

