func (this *Bingx) fetchTickersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbols := GetArg(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = nil
	if symbols != nil {
		symbols = this.MarketSymbols(symbols)
		var firstSymbol *string = this.SafeString(symbols, 0)
		if firstSymbol != nil {
			market = this.Market(firstSymbol)
		}
	}
	var typeVar *string = nil
	var typeVarparamsVariable []any = this.HandleMarketTypeAndParams("fetchTickers", market, params)
	typeVar = SafeStringPtr(GetValue(typeVarparamsVariable, 0))
	params = MapTyped(GetValue(typeVarparamsVariable, 1))
	var subType *string = nil
	var subTypeparamsVariable []any = this.HandleSubTypeAndParams("fetchTickers", market, params)
	subType = SafeStringPtr(GetValue(subTypeparamsVariable, 0))
	params = MapTyped(GetValue(subTypeparamsVariable, 1))
	var response map[string]any = nil
	if typeVar != nil && *typeVar == "spot" {

		response = MapTyped(PanicOnError((<-this.SpotV1PublicGetTicker24hr(params)).Raw))
	} else {
		if subType != nil && *subType == "inverse" {

			response = MapTyped(PanicOnError((<-this.CswapV1PublicGetMarketTicker(params)).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.SwapV2PublicGetQuoteTicker(params)).Raw))
		}
	}
	//
	// spot and swap
	//
	//     {
	//         "code": 0,
	//         "msg": "",
	//         "timestamp": 1720647285296,
	//         "data": [
	//             {
	//                 "symbol": "SOL-USD",
	//                 "priceChange": "-2.418",
	//                 "priceChangePercent": "-1.6900%",
	//                 "lastPrice": "140.574",
	//                 "lastQty": "1",
	//                 "highPrice": "146.190",
	//                 "lowPrice": "138.586",
	//                 "volume": "1464648.00",
	//                 "quoteVolume": "102928.12",
	//                 "openPrice": "142.994",
	//                 "closeTime": "1720647284976",
	//                 "bidPrice": "140.573",
	//                 "bidQty": "372",
	//                 "askPrice": "140.577",
	//                 "askQty": "58"
	//             },
	//             ...
	//         ]
	//     }
	//
	var tickers []any = SafeListTyped(response, "data")

	ch <- this.ParseTickers(tickers, symbols)
	return nil
}

/**
 * @method
 * @name bingx#fetchMarkPrice
 * @description fetches mark prices for the market
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20and%20Funding%20Rate
 * @see https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Price%20%26%20Current%20Funding%20Rate
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Bingx) FetchMarkPriceAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarkPriceBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bingx) fetchMarkPriceBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	var subType *string = nil
	var subTypeparamsVariable []any = this.HandleSubTypeAndParams("fetchMarkPrice", market, params, "linear")
	subType = SafeStringPtr(GetValue(subTypeparamsVariable, 0))
	params = MapTyped(GetValue(subTypeparamsVariable, 1))
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	var response map[string]any = nil
	if subType != nil && *subType == "inverse" {

		response = MapTyped(PanicOnError((<-this.CswapV1PublicGetMarketPremiumIndex(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.SwapV2PublicGetQuotePremiumIndex(this.Extend(request, params))).Raw))
	}
	if IsArray(GetValue(response, "data")) {

		ch <- this.ParseTicker(this.SafeDict(GetValue(response, "data"), 0, map[string]any{}), market)
		return nil
	}

	ch <- this.ParseTicker(GetValue(response, "data"), market)
	return nil
}

