func (this *Bingx) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// mark price
	// {
	//     "symbol": "string",
	//     "lastFundingRate": "string",
	//     "markPrice": "string",
	//     "indexPrice": "string",
	//     "nextFundingTime": "int64"
	// }
	//
	// spot
	//    {
	//        "symbol": "BTC-USDT",
	//        "openPrice": "26032.08",
	//        "highPrice": "26178.86",
	//        "lowPrice": "25968.18",
	//        "lastPrice": "26113.60",
	//        "volume": "1161.79",
	//        "quoteVolume": "30288466.44",
	//        "openTime": "1693081020762",
	//        "closeTime": "1693167420762",
	//  added 2023-11-10:
	//        "bidPrice": 16726.0,
	//        "bidQty": 0.05,
	//        "askPrice": 16726.0,
	//        "askQty": 0.05,
	//    }
	// swap
	//
	//    {
	//        "symbol": "BTC-USDT",
	//        "priceChange": "52.5",
	//        "priceChangePercent": "0.31%", // they started to add the percent sign in value
	//        "lastPrice": "16880.5",
	//        "lastQty": "2.2238",          // only present in swap!
	//        "highPrice": "16897.5",
	//        "lowPrice": "16726.0",
	//        "volume": "245870.1692",
	//        "quoteVolume": "4151395117.73",
	//        "openPrice": "16832.0",
	//        "openTime": 1672026667803,
	//        "closeTime": 1672026648425,
	//  added 2023-11-10:
	//        "bidPrice": 16726.0,
	//        "bidQty": 0.05,
	//        "askPrice": 16726.0,
	//        "askQty": 0.05,
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "symbol")
	var lastQty *string = this.SafeString(ticker, "lastQty")
	// in spot markets, lastQty is not present
	// it's (bad, but) the only way we can check the tickers origin
	var typeVar string = "swap"
	if lastQty == nil {
		typeVar = "spot"
	}
	market = MapTyped(this.SafeMarket(marketId, market, nil, typeVar))
	var symbol *string = SafeStringPtr(market["symbol"])
	var open *string = this.SafeString(ticker, "openPrice")
	var high *string = this.SafeString(ticker, "highPrice")
	var low *string = this.SafeString(ticker, "lowPrice")
	var close *string = this.SafeString(ticker, "lastPrice")
	var quoteVolume *string = this.SafeString(ticker, "quoteVolume")
	var baseVolume *string = this.SafeString(ticker, "volume")
	var percentage *string = this.SafeString(ticker, "priceChangePercent")
	if percentage != nil {
		percentage = SafeStringPtr(strings.Replace(*percentage, "%", "", 1))
	}
	var change *string = this.SafeString(ticker, "priceChange")
	var ts *int64 = this.SafeInteger(ticker, "closeTime")
	if ts != nil && *ts == 0 {
		ts = nil
	}
	var datetime *string = this.Iso8601(ts)
	var bid *string = this.SafeString(ticker, "bidPrice")
	var bidVolume *string = this.SafeString(ticker, "bidQty")
	var ask *string = this.SafeString(ticker, "askPrice")
	var askVolume *string = this.SafeString(ticker, "askQty")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     ts,
		"datetime":      datetime,
		"high":          high,
		"low":           low,
		"bid":           bid,
		"bidVolume":     bidVolume,
		"ask":           ask,
		"askVolume":     askVolume,
		"vwap":          nil,
		"open":          open,
		"close":         close,
		"last":          nil,
		"previousClose": nil,
		"change":        change,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"markPrice":     this.SafeString(ticker, "markPrice"),
		"indexPrice":    this.SafeString(ticker, "indexPrice"),
		"info":          ticker,
	}, market)
}

/**
 * @method
 * @name bingx#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://bingx-api.github.io/docs-v3/#/en/Spot/Account%20Endpoints/Query%20Assets
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Account%20Endpoints/Query%20account%20data
 * @see https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Trades%20Endpoints/Query%20Account%20Assets
 * @see https://bingx-api.github.io/docs-v3/#/en/Account%20and%20Wallet/Fund%20Account/Query%20Assets
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.standard] whether to fetch standard contract balances
 * @param {string} [params.type] the type of balance to fetch (spot, swap, funding) default is `spot`
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Bingx) FetchBalanceAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Bingx) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var response map[string]any = nil
	var standard any = nil
	var standardparamsVariable []any = this.HandleOptionBoolAndParams(params, "fetchBalance", "standard", false)
	standard = GetValue(standardparamsVariable, 0)
	params = MapTyped(GetValue(standardparamsVariable, 1))
	var subType *string = nil
	var subTypeparamsVariable []any = this.HandleSubTypeAndParams("fetchBalance", nil, params)
	subType = SafeStringPtr(GetValue(subTypeparamsVariable, 0))
	params = MapTyped(GetValue(subTypeparamsVariable, 1))
	var marketTypemarketTypeQueryVariable []any = this.HandleMarketTypeAndParams("fetchBalance", nil, params)
	var marketType *string = SafeStringPtr(GetValue(marketTypemarketTypeQueryVariable, 0))
	marketTypeQuery := GetValue(marketTypemarketTypeQueryVariable, 1)
	if standard == true {

		response = MapTyped(PanicOnError((<-this.ContractV1PrivateGetBalance(marketTypeQuery)).Raw))
	} else if (marketType != nil && *marketType == "funding") || (marketType != nil && *marketType == "fund") {

		response = MapTyped(PanicOnError((<-this.FundV1PrivateGetAccountBalance(marketTypeQuery)).Raw))
	} else if marketType != nil && *marketType == "spot" {

		response = MapTyped(PanicOnError((<-this.SpotV1PrivateGetAccountBalance(marketTypeQuery)).Raw))
	} else {
		if subType != nil && *subType == "inverse" {

			response = MapTyped(PanicOnError((<-this.CswapV1PrivateGetUserBalance(marketTypeQuery)).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.SwapV3PrivateGetUserBalance(marketTypeQuery)).Raw))
		}
	}

	ch <- this.ParseBalance(response)
	return nil
}
func (this *Bingx) ParseBalance(response any) any {
	//
	// standard
	//
	//     {
	//         "code": 0,
	//         "timestamp": 1721192833454,
	//         "data": [
	//             {
	//                 "asset": "USDT",
	//                 "balance": "4.72644300000000000000",
	//                 "crossWalletBalance": "4.72644300000000000000",
	//                 "crossUnPnl": "0",
	//                 "availableBalance": "4.72644300000000000000",
	//                 "maxWithdrawAmount": "4.72644300000000000000",
	//                 "marginAvailable": false,
	//                 "updateTime": 1721192833443
	//             },
	//         ]
	//     }
	//
	// spot
	//
	//     {
	//         "code": 0,
	//         "msg": "",
	//         "debugMsg": "",
	//         "data": {
	//             "balances": [
	//                 {
	//                     "asset": "USDT",
	//                     "free": "45.733046995800514",
	//                     "locked": "0"
	//                 },
	//             ]
	//         }
	//     }
	//
	// inverse swap
	//
	//     {
	//         "code": 0,
	//         "msg": "",
	//         "timestamp": 1721191833813,
	//         "data": [
	//             {
	//                 "asset": "SOL",
	//                 "balance": "0.35707951",
	//                 "equity": "0.35791051",
	//                 "unrealizedProfit": "0.00083099",
	//                 "availableMargin": "0.35160653",
	//                 "usedMargin": "0.00630397",
	//                 "freezedMargin": "0",
	//                 "shortUid": "12851936"
	//             }
	//         ]
	//     }
	//
	// linear swap
	//
	//     {
	//         "code": 0,
	//         "msg": "",
	//         "data": [
	//             {
	//                 "userId": "116***295",
	//                 "asset": "USDT",
	//                 "balance": "194.8212",
	//                 "equity": "196.7431",
	//                 "unrealizedProfit": "1.9219",
	//                 "realisedProfit": "-109.2504",
	//                 "availableMargin": "193.7609",
	//                 "usedMargin": "1.0602",
	//                 "freezedMargin": "0.0000",
	//                 "shortUid": "12851936"
	//             }
	//         ]
	//     }
	//
	var result map[string]any = map[string]any{
		"info": response,
	}
	var contractBalances []any = SafeListTyped(response, "data")
	var firstContractBalances map[string]any = SafeMapTyped(contractBalances, 0)
	var isContract bool = (firstContractBalances != nil)
	var spotData map[string]any = SafeMapTyped(response, "data")
	var spotBalances []any = SafeList2Typed(spotData, "balances", "assets")
	if isContract {
		for i := 0; i < len(contractBalances); i++ {
			var balance map[string]any = SafeMapTyped(contractBalances, i)
			var currencyId *string = this.SafeString(balance, "asset")
			if currencyId == nil {
				break
			}
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["free"] = this.SafeString2(balance, "availableMargin", "availableBalance")
			account["used"] = this.SafeString(balance, "usedMargin")
			account["total"] = this.SafeString(balance, "maxWithdrawAmount")
			if code != nil {
				AddElementToObject(result, code, account)
			}
		}
	} else {
		for i := 0; i < len(spotBalances); i++ {
			var balance map[string]any = SafeMapTyped(spotBalances, i)
			var currencyId *string = this.SafeString(balance, "asset")
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["free"] = this.SafeString(balance, "free")
			account["used"] = this.SafeString(balance, "locked")
			if code != nil {
				AddElementToObject(result, code, account)
			}
		}
	}
	return this.SafeBalance(result)
}

