	//       "time": 1649818185647,
	//       "updateTime": 1649818185647,
	//       "origQuoteOrderQty": "0"
	//       "fee": "-0.01"
	//   }
	//
	//
	// linear swap
	// createOrder, createOrders
	//
	//    {
	//      "symbol": "BTC-USDT",
	//      "orderId": 1590973236294713344,
	//      "side": "BUY",
	//      "positionSide": "LONG",
	//      "type": "LIMIT"
	//    }
	//
	// inverse swap createOrder
	//
	//     {
	//         "orderId": 1809841379603398656,
	//         "symbol": "SOL-USD",
	//         "positionSide": "LONG",
	//         "side": "BUY",
	//         "type": "LIMIT",
	//         "price": 100,
	//         "quantity": 1,
	//         "stopPrice": 0,
	//         "workingType": "",
	//         "timeInForce": ""
	//     }
	//
	// fetchOrder, fetchOpenOrders, fetchClosedOrders
	//
	//     {
	//         "symbol": "BTC-USDT",
	//         "orderId": 1709036527545438208,
	//         "side": "BUY",
