func (this *Bingx) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//    {
	//        "amount":"0.00999800",
	//        "coin":"PAXG",
	//        "network":"ETH",
	//        "status":1,
	//        "address":"0x788cabe9236ce061e5a892e1a59395a81fc8d62c",
	//        "addressTag":"",
	//        "txId":"0xaad4654a3234aa6118af9b4b335f5ae81c360b2394721c019b5d1e75328b09f3",
	//        "insertTime":1599621997000,
	//        "transferType":0,
	//        "unlockConfirm":"12/12", // confirm times for unlocking
	//        "confirmTimes":"12/12"
	//    }
	//
	// fetchWithdrawals
	//
	//    {
	//        "address": "0x94df8b352de7f46f64b01d3666bf6e936e44ce60",
	//        "amount": "8.91000000",
	//        "applyTime": "2019-10-12 11:12:02",
	//        "coin": "USDT",
	//        "id": "b6ae22b3aa844210a7041aee7589627c",
	//        "withdrawOrderId": "WITHDRAWtest123",
	//        "network": "ETH",
	//        "transferType": 0
	//        "status": 6,
	//        "transactionFee": "0.004",
	//        "confirmNo":3,
	//        "info": "The address is not valid. Please confirm with the recipient",
	//        "txId": "0xb5ef8c13b968a406cc62a93a8bd80f9e9a906ef1b3fcf20a2e48573c17659268"
	//    }
	//
	// withdraw
	//
	//     {
	//         "code":0,
	//         "timestamp":1705274263621,
	//         "data":{
	//             "id":"1264246141278773252"
	//         }
	//     }
	//
	// parse withdraw-type output first...
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var data map[string]any = SafeMapTyped(transaction, "data")
	var dataId *string = func() *string {
		if data == nil {
			return nil
		}
		return this.SafeString(data, "id")
	}()
	var id *string = this.SafeString(transaction, "id", dataId)
	var address *string = this.SafeString(transaction, "address")
	var tag *string = this.SafeString(transaction, "addressTag")
	var timestamp *int64 = this.SafeInteger2(transaction, "insertTime", "timestamp")
	var datetime *string = this.Iso8601(timestamp)
	if timestamp == nil {
		datetime = this.SafeString(transaction, "applyTime")
		timestamp = this.Parse8601(datetime)
	}
	var network *string = this.SafeString(transaction, "network")
	var currencyId *string = this.SafeString(transaction, "coin")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	if (code != nil) && (network != nil) && (code != network && (code == nil || network == nil || *code != *network)) && (GetIndexOf(code, network) >= 0) {
		if network != nil {
			code = SafeStringPtr(strings.Replace(*code, *network, "", 1))
		}
	}
	var rawType *string = this.SafeString(transaction, "transferType")
	var typeVar string = "withdrawal"
	if rawType != nil && *rawType == "0" {
		typeVar = "deposit"
	}
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        this.SafeString(transaction, "txId"),
		"type":        typeVar,
		"currency":    code,
		"network":     this.NetworkIdToCode(network, code),
		"amount":      this.SafeNumber(transaction, "amount"),
		"status":      this.ParseTransactionStatus(this.SafeString(transaction, "status")),
		"timestamp":   timestamp,
		"datetime":    datetime,
		"address":     address,
		"addressFrom": nil,
		"addressTo":   address,
		"tag":         tag,
		"tagFrom":     tag,
		"tagTo":       nil,
		"updated":     nil,
		"comment":     this.SafeString(transaction, "info"),
		"fee": map[string]any{
			"currency": code,
			"cost":     this.SafeNumber(transaction, "transactionFee"),
			"rate":     nil,
		},
		"internal": nil,
	}
}
func (this *Bingx) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"0":  "pending",
		"1":  "ok",
		"10": "pending",
		"20": "rejected",
		"30": "ok",
		"40": "rejected",
		"50": "ok",
		"60": "pending",
		"70": "rejected",
		"2":  "pending",
		"3":  "rejected",
		"4":  "pending",
		"5":  "rejected",
		"6":  "ok",
	}
	return this.SafeString(statuses, status, status)
}

/**
 * @method
 * @name bingx#setMarginMode
 * @description set margin mode to 'cross' or 'isolated'
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Trades%20Endpoints/Change%20Margin%20Type
 * @see https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Trades%20Endpoints/Set%20Margin%20Type
 * @param {string} marginMode 'cross' or 'isolated'
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} response from the exchange
 */
func (this *Bingx) SetMarginModeAsync(marginMode any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.setMarginModeBody(ch, marginMode, optionalArgs...)
	return ch
}
func (this *Bingx) setMarginModeBody(ch chan any, marginMode any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " setMarginMode() requires a symbol argument"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	if GetValue(market, "type") != "swap" {
		panic(BadSymbol(this.Id + " setMarginMode() supports swap contracts only"))
	}
	marginMode = ToUpper(marginMode)
	if IsEqual(marginMode, "CROSS") {
		marginMode = "CROSSED"
	}
	if (!IsEqual(marginMode, "ISOLATED")) && (!IsEqual(marginMode, "CROSSED")) {
		panic(BadRequest(this.Id + " setMarginMode() marginMode argument should be isolated or cross"))
	}
	var request map[string]any = map[string]any{
		"symbol":     market["id"],
		"marginType": marginMode,
	}
	var subType *string = nil
	var subTypeparamsVariable []any = this.HandleSubTypeAndParams("setMarginMode", market, params)
	subType = SafeStringPtr(GetValue(subTypeparamsVariable, 0))
	params = MapTyped(GetValue(subTypeparamsVariable, 1))
	if subType != nil && *subType == "inverse" {

		ch <- PanicOnError((<-this.CswapV1PrivatePostTradeMarginType(this.Extend(request, params))).Raw)
		return nil
	} else {

		ch <- PanicOnError((<-this.SwapV2PrivatePostTradeMarginType(this.Extend(request, params))).Raw)
		return nil
	}
}
