	//         "availableLongVal": "0.0",
	//         "availableShortVal": "0.0",
	//         "maxPositionLongVal": "0.0",
	//         "maxPositionShortVal": "0.0"
	//     }
	//
	// inverse swap
	//
	//     {
	//         "symbol": "SOL-USD",
	//         "longLeverage": 5,
	//         "shortLeverage": 5,
	//         "maxLongLeverage": 50,
	//         "maxShortLeverage": 50,
