func (this *Bingx) editOrderBody(ch chan any, id any, symbol any, typeVar any, side any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var amount *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = amount
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 1, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	if GetValue(market, "inverse") == true {
		panic(NotSupported(this.Id + " editOrder() is not supported for inverse swap markets"))
	}
	var request any = this.CreateOrderRequest(symbol, typeVar, side, amount, price, params)
	AddElementToObject(request, "cancelOrderId", id)
	AddElementToObject(request, "cancelReplaceMode", "STOP_ON_FAILURE")
	var response map[string]any = nil
	if GetValue(market, "swap") == true {

		response = MapTyped(PanicOnError((<-this.SwapV1PrivatePostTradeCancelReplace(request)).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.SpotV1PrivatePostTradeOrderCancelReplace(request)).Raw))
	}
	var data map[string]any = MapTyped(this.SafeDict(response, "data", map[string]any{}))

	ch <- this.ParseOrder(data, market)
	return nil
}

